import java.util.*;
import java.io.*;

public class Main {
    static class Fraction {
        long num, den;
        Fraction(long num, long den) {
            this.num = num;
            this.den = den;
        }
    }

    static Pair<Long, Long> getFractionBounds(int x, int y, int b) {
        long minVal = (long) b * x / y;
        long maxVal = ((long) b * x + y - 1) / y;
        return new Pair<>(minVal, maxVal);
    }

    static long computeGCD(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static void findClosestFraction(int x, int y, int n) {
        List<Fraction> candidates = new ArrayList<>();
        for (int b = 1; b <= n; b++) {
            Pair<Long, Long> bounds = getFractionBounds(x, y, b);
            candidates.add(new Fraction(bounds.getKey(), b));
            candidates.add(new Fraction(bounds.getValue(), b));
        }

        candidates.sort((f1, f2) -> {
            long diff1 = Math.abs((long) x * f1.den * f2.den - f1.num * f2.den * y);
            long diff2 = Math.abs((long) x * f1.den * f2.den - f2.num * f1.den * y);
            if (diff1 != diff2) return Long.compare(diff1, diff2);
            if (f1.den != f2.den) return Long.compare(f1.den, f2.den);
            return Long.compare(f1.num, f2.num);
        });

        Fraction best = candidates.get(0);
        System.out.println(best.num + "/" + best.den);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int x = Integer.parseInt(parts[0]);
        int y = Integer.parseInt(parts[1]);
        int n = Integer.parseInt(parts[2]);
        findClosestFraction(x, y, n);
    }

    // Simple Pair class since Java 8 doesn't have a built-in Pair
    static class Pair<K, V> {
        private K key;
        private V value;
        public Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }
        public K getKey() { return key; }
        public V getValue() { return value; }
    }
}
